def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals based on the start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    # Initialize the merged list with a copy of the first interval
    merged = [list(sorted_intervals[0])]

    for current in sorted_intervals[1:]:
        last_merged = merged[-1]

        # Check for overlap or touching intervals
        if current[0] <= last_merged[1]:
            # Merge by updating the end of the last interval
            last_merged[1] = max(last_merged[1], current[1])
        else:
            merged.append(list(current))

    return merged

import heapq

def toposort(nodes, edges):
    # Initialize adjacency list with sets to handle duplicates and allow O(1) lookup
    # This ensures duplicate edges do not artificially increase the indegree count
    adj = {node: set() for node in nodes}
    indegree = {node: 0 for node in nodes}

    # Build the graph
    for src, dst in edges:
        if dst not in adj[src]:
            adj[src].add(dst)
            indegree[dst] += 1

    # Initialize heap with all nodes having indegree 0
    # Converting to list and heapifying is O(N log N), which handles lex order
    zero_indeg = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(zero_indeg)

    result = []

    while zero_indeg:
        # Lexicographically smallest node
        curr = heapq.heappop(zero_indeg)
        result.append(curr)

        # Process neighbors
        for neighbor in adj[curr]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(zero_indeg, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")

    if not items:
        return []

    batches = []
    current_batch = []
    current_weight = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("Invalid weight")

        if current_weight + weight > limit:
            batches.append(current_batch)
            current_batch = [name]
            current_weight = weight
        else:
            current_batch.append(name)
            current_weight += weight

    if current_batch:
        batches.append(current_batch)

    return batches
